// ============================================================================
//  offgrid-decoders - reusable C++11 decoders for radio text and picture
//  modes (part of OFFgrid-SDR TUI, https://github.com/solariun/offgrid-sdr).
//  SPDX-License-Identifier: GPL-3.0-or-later
// ----------------------------------------------------------------------------
//  File:   src/decoders/DrmDemoData.cpp
//  Layer:  Library liboffgrid-decoders
//
//  What this file does
//  -------------------
//  The demo DRM stations' material, byte for byte as OFFgrid-SDR's JS
//  carries it in index.html (diddy-boy, https://github.com/solariun/
//  offgrid-sdr: the "drmdemoaac", "drmdemoxhe" and "drmdemoslide" blocks,
//  base64 there):
//    - kDemoAac: the 12-second original jingle in AAC (24 kHz, mono, no
//      SBR), 300 frames encoded with FAAC's DRM encoder (with OFFgrid-SDR's
//      fixes), each stored as [length, 2 bytes LE][the DRM CRC byte][AU];
//    - kDemoXhe: the same jingle in xHE-AAC (libxaac), 150 frames (12.8 s),
//      each [length, 2 bytes LE][frame];
//    - kDemoSlidePng: the SlideShow picture, a 128 x 128 PNG.
//  (The DRM signal they go into follows Dream, TU Darmstadt,
//  GPL-2.0-or-later, licenses/dream-COPYING.txt: see DrmEncoders.cpp.)
//
//  How it fits in
//  --------------
//  Read by DrmEncoders.cpp (drmDemoAacFrames, drmDemoXheFrames,
//  drmDemoSlidePng).  Generated from index.html: don't edit by hand.
//
//  Contributing
//  ------------
//  If the JS's demo material changes, regenerate (base64-decode the blocks
//  and print the bytes).
// ============================================================================
